<script setup lang="ts">
import { ref, computed, watch } from 'vue'
import { api } from '../api'
import { user, usePage, perform, busy } from '../state'
import { decimal, requestKey, buildRedemptionGroup } from '../domain'
import type { Row } from '../domain'
import PageHeader from '../components/PageHeader.vue'
import DataTable from '../components/DataTable.vue'
import LoadState from '../components/LoadState.vue'
import TradeDialog from '../components/TradeDialog.vue'
const portfolio = ref<Row>({ positions: [], accounts: [] }), filter = ref(''), fund = ref<Row | null>(null), trade = ref(false), source = ref<number>(), groupOpen = ref(false), groupFund = ref(''), allocations = ref<Record<string, string>>({}), quotes = ref<Row[]>([]), groupKey = ref(requestKey()), funds = ref<Row[]>([])
const { loading, error, load } = usePage(async () => { const result = await Promise.all([api.get('/portfolio'), api.get('/funds')]); portfolio.value = result[0]; funds.value = result[1] })
const positions = computed(() => portfolio.value.positions.filter((p: Row) => !filter.value || String(p.tradingAccountId) === filter.value))
const groupProducts = computed(() => funds.value.filter(f => portfolio.value.positions.some((p: Row) => p.fundClassId === f.id)))
const groupRows = computed(() => portfolio.value.positions.filter((p: Row) => String(p.fundClassId) === groupFund.value))
watch(groupFund, () => { allocations.value = {}; quotes.value = []; groupKey.value = requestKey() })
function redeem(row: Row) { fund.value = funds.value.find(f => f.id === row.fundClassId) || { id: row.fundClassId, name: row.fundName }; source.value = row.tradingAccountId; trade.value = true }
function groupPayload() { return buildRedemptionGroup(Number(groupFund.value),groupRows.value.map((p:Row)=>({tradingAccountId:p.tradingAccountId,shares:allocations.value[p.tradingAccountId] || ''})),groupKey.value) }
async function groupQuote() { await perform(async () => { const data = groupPayload(); quotes.value = await Promise.all(data.allocations.map(async (a: Row) => ({...await api.post('/trades/quotes', { type: 'REDEMPTION', fundClassId: data.fundClassId, ...a }),tradingAccountId:a.tradingAccountId}))) }) }
async function groupSubmit() { await perform(() => api.post('/redemption-groups', groupPayload()), async () => { groupOpen.value = false; await load() }) }
</script>
<template><PageHeader title="我的资产" subtitle="逐个账户记录，汇总查看你的模拟投资。"><RouterLink to="/market" class="button primary">发现基金 ↗</RouterLink><button class="button" @click="load">刷新</button></PageHeader><LoadState :loading="loading" :error="error" @retry="load"/><div v-if="!user?.opened" class="notice warning">完成模拟开户与风险测评后，即可绑定模拟卡并开始交易。 <RouterLink to="/profile">去开户与测评 →</RouterLink></div><section class="asset-hero"><p class="muted">总资产（元）</p><div class="asset-value">{{ decimal(portfolio.totalAssets) }}</div><div class="hero-bottom"><div>累计模拟收益<b>{{ decimal(portfolio.totalIncome) }}</b></div><div>持仓市值<b>{{ decimal(portfolio.invested) }}</b></div></div></section><div class="metrics"><div class="metric"><p>可用资金（元）</p><b>{{ decimal(portfolio.available) }}</b><small>可用于指定账户购入</small></div><div class="metric"><p>冻结资金（元）</p><b>{{ decimal(portfolio.frozen) }}</b><small>等待确认的购入申请</small></div><div class="metric"><p>在途资产（元）</p><b>{{ decimal(portfolio.pending) }}</b><small>认购、赎回及其他待支付</small></div><div class="metric"><p>持有产品</p><b>{{ new Set(portfolio.positions.map((p: Row) => p.fundClassId)).size }}</b><small>{{ portfolio.accounts.length }} 个独立交易账户</small></div></div><section class="panel"><div class="section-title"><h2>我的持仓</h2><button class="button" :disabled="!portfolio.positions.length" @click="groupOpen = true">多账户汇总赎回</button></div><div class="toolbar filters"><select v-model="filter"><option value="">所有交易账户</option><option v-for="account in portfolio.accounts" :key="account.id" :value="String(account.tradingAccountId || account.id)">{{ account.bankName }} · {{ account.accountNo }}</option></select><span class="muted">冻结份额暂不可再次赎回</span></div><DataTable :rows="positions" :columns="[{key:'fundName',label:'基金'}, {key:'bankName',label:'来源银行'}, {key:'tradingAccountId',label:'交易账户'}, {key:'shares',label:'总份额',kind:'shares'}, {key:'availableShares',label:'可用份额',kind:'shares'}, {key:'frozenShares',label:'冻结份额',kind:'shares'}, {key:'nav',label:'当前净值',kind:'nav'}, {key:'marketValue',label:'市值（元）',kind:'money'}, {key:'cost',label:'成本（元）',kind:'money'}, {key:'profit',label:'持仓收益（元）',kind:'money'}]" empty="尚无持仓，先去基金市场选一只模拟产品"><template #cell-fundName="{row}"><RouterLink :to="'/funds/' + row.fundClassId">{{ row.fundName }}</RouterLink></template><template #actions="{row}"><button class="text-button" @click="redeem(row)">赎回</button></template></DataTable></section><section class="panel"><div class="section-title"><h2>逐账户资产</h2><RouterLink to="/accounts">管理资金 →</RouterLink></div><DataTable :rows="portfolio.accounts" :columns="[{key:'accountNo',label:'交易账户'}, {key:'bankName',label:'结算银行'}, {key:'available',label:'可用资金（元）',kind:'money'}, {key:'frozen',label:'冻结资金（元）',kind:'money'}, {key:'invested',label:'持仓市值（元）',kind:'money'}, {key:'pending',label:'在途（元）',kind:'money'}, {key:'totalAssets',label:'总资产（元）',kind:'money'}]"/></section><TradeDialog v-model="trade" :fund="fund" type="REDEMPTION" :account-id="source" @submitted="load"/><el-dialog v-model="groupOpen" title="多账户汇总赎回" width="760px"><p class="notice">每个交易账户生成独立子单，分别确认与原路回款。整组受理时同时校验，任何一组不符合条件均不受理。</p><label><span>赎回产品</span><select v-model="groupFund" required><option disabled value="">请选择持有的基金</option><option v-for="f in groupProducts" :key="f.id" :value="String(f.id)">{{ f.name }}</option></select></label><div v-for="p in groupRows" :key="p.tradingAccountId" class="inline-form" style="margin-top:15px"><label><span>{{ p.bankName }} · 交易账户 {{ p.tradingAccountId }} · 可用 {{ decimal(p.availableShares, 4) }} 份</span><input v-model="allocations[p.tradingAccountId]" inputmode="decimal" placeholder="本账户赎回份额，留空则不参与" @input="quotes = []; groupKey = requestKey()"/></label></div><DataTable v-if="quotes.length" :rows="quotes" :columns="[{key:'tradingAccountId',label:'来源账户'}, {key:'nav',label:'参考净值',kind:'nav'}, {key:'fee',label:'预估费用',kind:'money'}, {key:'netAmount',label:'预估回款',kind:'money'}, {key:'applicationDate',label:'交易日'}]"/><div class="form-actions"><button class="button" :disabled="busy > 0 || !groupFund" @click="groupQuote">逐账户预估</button><button class="button primary" :disabled="busy > 0 || !quotes.length" @click="groupSubmit">提交整组申请</button></div></el-dialog></template>
